import * as T from '../../vendor/three/three.module.js';
import { routeFrame } from './ChaseRoute.js';

// Interpretação volumétrica da referência illustrated-fairy-v1: coque castanho,
// flor dourada, vestido creme, quatro asas cor de mel e varinha de estrela.
const COLORS = Object.freeze({ skin: '#edb77f', blush: '#d88662', hair: '#744020', lock: '#a4652e',
  cream: '#fff0b7', gold: '#dda03b', eye: '#38261e', white: '#fff9dd' });

/** Fadinha em malhas fechadas, sem prancha/sprite e com voo derivado do relógio da fase. */
export class ChaseFairyModel {
  /** Agrupa peças por material; recursos pertencem exclusivamente ao compositor. */
  constructor(own) {
    this.own = own;
    this.root = new T.Group(); this.root.name = 'Fadinha3D';
    this.anchor = new T.Vector3();
    this.bodyMaterial = own(new T.MeshStandardMaterial({ vertexColors: true, roughness: .86, metalness: 0,
      emissive: '#b98035', emissiveIntensity: .09 }));
    this.wingMaterial = own(new T.MeshStandardMaterial({ color: '#ffe3a1', emissive: '#bd8637', emissiveIntensity: .2,
      roughness: .55, metalness: 0, transparent: true, opacity: .68, depthWrite: false }));
    this.glowMaterial = own(new T.MeshBasicMaterial({ color: '#ffe9aa', transparent: true, opacity: .065,
      blending: T.AdditiveBlending, depthWrite: false }));
    this.starMaterial = own(new T.MeshStandardMaterial({ color: '#fff0ab', emissive: '#ffce69',
      emissiveIntensity: 1.6, roughness: .5 }));
    const body = [];
    this.ellipsoid(body, 'cream', [0, .29, 0], [.095, .13, .065]);
    this.ellipsoid(body, 'gold', [0, .205, 0], [.105, .023, .073]);
    this.ellipsoid(body, 'skin', [0, .43, -.015], [.027, .05, .028]);
    this.ellipsoid(body, 'skin', [0, .535, -.015], [.145, .15, .122]);
    this.ellipsoid(body, 'hair', [0, .575, .025], [.154, .139, .115]);
    this.ellipsoid(body, 'hair', [.045, .71, .055], [.105, .095, .09]);
    for (let i = 0; i < 7; i++) {
      const a = i * Math.PI * 2 / 7;
      this.ellipsoid(body, 'lock', [.045 + Math.cos(a) * .065, .71 + Math.sin(a) * .06, .105], [.023, .035, .018]);
    }
    this.piece(body, new T.SphereGeometry(1, 16, 10), 'hair', [-.025, .638, -.112], [.112, .036, .033],
      new T.Quaternion().setFromAxisAngle(new T.Vector3(0, 0, 1), -.24));
    // Franja oblíqua e mechas laterais curtas conservam a testa e a expressão abertas.
    for (const side of [-1, 1]) {
      this.ellipsoid(body, 'hair', [side * .127, .583, -.046], [.034, .074, .047]);
      this.ellipsoid(body, 'skin', [side * .143, .53, -.005], [.025, .034, .024]);
      this.ellipsoid(body, 'white', [side * .057, .54, -.127], [.034, .034, .009]);
      this.ellipsoid(body, 'eye', [side * .054, .537, -.135], [.019, .026, .006]);
      this.ellipsoid(body, 'white', [side * .054 - .005, .547, -.141], [.006, .008, .003]);
      this.ellipsoid(body, 'blush', [side * .09, .496, -.111], [.025, .012, .007]);
    }
    this.ellipsoid(body, 'skin', [0, .509, -.14], [.016, .018, .015]);
    this.ellipsoid(body, 'blush', [0, .478, -.13], [.022, .005, .004]);
    for (let i = 0; i < 5; i++) {
      const a = i * Math.PI * 2 / 5;
      this.ellipsoid(body, 'gold', [-.073 + Math.cos(a) * .025, .697 + Math.sin(a) * .025, -.035], [.018, .02, .012]);
    }
    this.ellipsoid(body, 'cream', [-.073, .697, -.05], [.014, .014, .008]);
    this.dress(body);
    this.batch(this.root, body, 'CorpoVestidoCoque');
    this.arms = []; this.legs = []; this.wings = [];
    for (const side of [-1, 1]) {
      const arm = this.joint('BracoDaFada', side * .087, .365, 0);
      const parts = [];
      this.ellipsoid(parts, 'cream', [side * .015, -.02, 0], [.045, .046, .04]);
      this.ellipsoid(parts, 'skin', [side * .034, -.085, -.018], [.026, .075, .026]);
      this.ellipsoid(parts, 'skin', [side * .06, -.148, -.037], [.032, .029, .027]);
      this.batch(arm, parts, 'MangaBracoMao'); this.arms.push(arm);
      const leg = this.joint('PernaDaFada', side * .046, .115, .005);
      const pieces = [];
      this.ellipsoid(pieces, 'skin', [0, -.057, .025], [.025, .071, .026]);
      this.ellipsoid(pieces, 'skin', [0, -.115, .055], [.022, .035, .025]);
      this.ellipsoid(pieces, 'gold', [0, -.141, .035], [.029, .025, .046]);
      this.batch(leg, pieces, 'PernaSapatilha'); this.legs.push(leg);
      const wing = this.joint('AsasDaFada', side * .025, .35, .072);
      wing.scale.x = side;
      const geometry = this.wingGeometry();
      const mesh = new T.Mesh(own(geometry), this.wingMaterial); mesh.name = 'AsasComEspessura'; wing.add(mesh);
      const ribs = [];
      for (const [start, end] of [ [[.015, .005, -.01], [.32, .27, -.015]], [[.02, 0, -.01], [.38, -.09, -.015]],
        [[.07, .06, -.01], [.24, .25, -.015]], [[.08, -.02, -.01], [.3, -.12, -.015]] ]) {
        this.rod(ribs, 'gold', start, end, .0035);
      }
      this.batch(wing, ribs, 'NervurasDasAsas'); this.wings.push(wing);
    }
    const wand = [];
    this.rod(wand, 'gold', [.06, -.145, -.04], [.14, .06, -.08], .006);
    this.batch(this.arms[1], wand, 'Varinha');
    const star = new T.Shape();
    for (let i = 0; i < 10; i++) {
      const a = Math.PI / 2 + i * Math.PI / 5, r = i % 2 ? .024 : .057;
      if (i) star.lineTo(Math.cos(a) * r, Math.sin(a) * r); else star.moveTo(Math.cos(a) * r, Math.sin(a) * r);
    }
    star.closePath();
    this.star = new T.Mesh(own(new T.ExtrudeGeometry(star, { depth: .012, bevelEnabled: true,
      bevelSegments: 1, bevelSize: .004, bevelThickness: .003, steps: 1 })), this.starMaterial);
    this.star.name = 'EstrelaLuminosa'; this.star.position.set(.14, .06, -.085); this.arms[1].add(this.star);
    // Halo em volume, sem bloom de tela inteira, textura, billboard ou passe adicional.
    this.glow = new T.Mesh(own(new T.SphereGeometry(1, 12, 8)), this.glowMaterial);
    this.glow.name = 'HaloVolumetrico'; this.glow.position.set(0, .34, 0); this.glow.scale.set(.21, .29, .17);
    this.root.add(this.glow);
    this.root.traverse(object => {
      if (!object.isMesh) return;
      // A fonte luminosa fica dentro da fada: sua roupa não pode eclipsar a própria luz.
      object.userData.fairyLuminous = true; object.castShadow = false; object.receiveShadow = false;
    });
    this.root.userData.authoring = 'Modelo geométrico próprio: referência dourada da fada, sem sprite; asas com espessura e peças agrupadas.';
  }

  /** Acrescenta um pivô local para asas/membros, liberado junto da hierarquia do compositor. */
  joint(name, x, y, z) {
    const joint = new T.Group(); joint.name = name; joint.position.set(x, y, z); this.root.add(joint); return joint;
  }

  /** Acrescenta geometria transformada à coleção temporária; o original é descartado após a fusão. */
  piece(parts, geometry, color, position, scale = [1, 1, 1], quaternion = new T.Quaternion()) {
    geometry.applyMatrix4(new T.Matrix4().compose(new T.Vector3(...position), quaternion, new T.Vector3(...scale)));
    parts.push({ geometry, color: new T.Color(COLORS[color]) });
  }

  /** Modela volumes com uma tesselação pequena, apropriada à escala da fada no gameplay. */
  ellipsoid(parts, color, position, scale) {
    this.piece(parts, new T.SphereGeometry(1, 12, 8), color, position, scale);
  }

  /** Constrói nervuras e haste como cilindros fechados, com orientação entre dois pontos. */
  rod(parts, color, start, end, radius) {
    const a = new T.Vector3(...start), b = new T.Vector3(...end), axis = b.clone().sub(a);
    const rotation = new T.Quaternion().setFromUnitVectors(new T.Vector3(0, 1, 0), axis.clone().normalize());
    this.piece(parts, new T.CylinderGeometry(radius, radius, axis.length(), 5), color, a.add(b).multiplyScalar(.5).toArray(), [1, 1, 1], rotation);
  }

  /** Forma a saia com pétalas em volume e borda ondulada; não é um cone plano recortado. */
  dress(parts) {
    const geometry = new T.CylinderGeometry(.075, .155, .17, 24, 4), p = geometry.attributes.position;
    for (let i = 0; i < p.count; i++) {
      const a = Math.atan2(p.getZ(i), p.getX(i)), y = p.getY(i), fold = 1 + Math.cos(a * 7) * .07;
      p.setXYZ(i, p.getX(i) * fold, y - Math.cos(a * 7) * .012 * Math.max(0, -y / .085), p.getZ(i) * fold * .8);
    }
    geometry.computeVertexNormals(); this.piece(parts, geometry, 'cream', [0, .17, 0]);
    for (let i = 0; i < 7; i++) {
      const a = i / 7 * Math.PI * 2;
      this.ellipsoid(parts, 'gold', [Math.sin(a) * .125, .1, Math.cos(a) * .1], [.036, .015, .025]);
    }
  }

  /** Une posições/normais/cores em uma chamada por conjunto articulado, sem guardar malhas intermediárias. */
  batch(parent, parts, name) {
    const positions = [], normals = [], colors = [];
    for (const part of parts) {
      const geometry = part.geometry.index ? part.geometry.toNonIndexed() : part.geometry;
      const p = geometry.attributes.position, n = geometry.attributes.normal;
      for (let i = 0; i < p.count; i++) {
        positions.push(p.getX(i), p.getY(i), p.getZ(i)); normals.push(n.getX(i), n.getY(i), n.getZ(i));
        const shade = .88 + .12 * Math.max(0, n.getY(i));
        colors.push(part.color.r * shade, part.color.g * shade, part.color.b * shade);
      }
      if (geometry !== part.geometry) geometry.dispose(); part.geometry.dispose();
    }
    const geometry = this.own(new T.BufferGeometry());
    geometry.setAttribute('position', new T.Float32BufferAttribute(positions, 3));
    geometry.setAttribute('normal', new T.Float32BufferAttribute(normals, 3));
    geometry.setAttribute('color', new T.Float32BufferAttribute(colors, 3));
    const mesh = new T.Mesh(geometry, this.bodyMaterial); mesh.name = name; parent.add(mesh); return mesh;
  }

  /** Dá espessura lenticular às quatro asas, com superfície curva fechada nas duas faces. */
  wingGeometry() {
    const positions = [], indices = [];
    for (const [cx, cy, rx, ry, angle] of [[.225, .16, .12, .245, -.65], [.24, -.075, .16, .09, .3]]) {
      const start = positions.length / 3, rings = 5, segments = 20;
      for (const face of [-1, 1]) for (let ring = 0; ring <= rings; ring++) for (let i = 0; i <= segments; i++) {
        const r = ring / rings, a = i / segments * Math.PI * 2, x = Math.cos(a) * rx * r, y = Math.sin(a) * ry * r;
        positions.push(cx + x * Math.cos(angle) - y * Math.sin(angle), cy + x * Math.sin(angle) + y * Math.cos(angle), face * .014 * (1 - r * r));
      }
      const count = (rings + 1) * (segments + 1);
      for (let face = 0; face < 2; face++) for (let ring = 0; ring < rings; ring++) for (let i = 0; i < segments; i++) {
        const a = start + face * count + ring * (segments + 1) + i, b = a + segments + 1;
        if (face) indices.push(a, b, a + 1, b, b + 1, a + 1); else indices.push(a, a + 1, b, b, a + 1, b + 1);
      }
    }
    const geometry = new T.BufferGeometry(); geometry.setAttribute('position', new T.Float32BufferAttribute(positions, 3));
    geometry.setIndex(indices); geometry.computeVertexNormals(); return geometry;
  }

  /** Voa sobre a cabeça animada, inclusive em curvas/queda; pausa e restore não acumulam movimento extra. */
  apply(state, girlModel) {
    girlModel.head.updateWorldMatrix(true, false);
    this.anchor.set(0, .42, 0).applyMatrix4(girlModel.head.matrixWorld);
    const yaw = routeFrame(state.distance).yaw;
    const side = .19 + Math.sin(state.time * 1.7) * .075;
    this.root.position.copy(this.anchor);
    this.root.position.x += Math.cos(yaw) * side + Math.sin(yaw) * .24;
    this.root.position.z += -Math.sin(yaw) * side + Math.cos(yaw) * .24;
    this.root.position.y += .32 + Math.sin(state.time * 2.3) * .045;
    this.root.rotation.set(-.06 + Math.sin(state.time * 2.3) * .025, yaw + Math.sin(state.time * 1.4) * .1, Math.sin(state.time * 1.7) * .055);
    for (let i = 0; i < 2; i++) {
      const side = i ? 1 : -1;
      this.wings[i].rotation.y = side * (.28 + Math.sin(state.time * 22) * .65);
      this.arms[i].rotation.set(-.25 + Math.sin(state.time * 2.3 + i) * .08, 0, side * .22);
      this.legs[i].rotation.set(.32 + Math.sin(state.time * 2.3 + i * 2) * .1, 0, side * .09);
    }
    this.starMaterial.emissiveIntensity = 1.45 + Math.sin(state.time * 2.3) * .15;
    this.root.visible = true; this.root.updateMatrixWorld(true);
  }
}
